class NumericalError(Exception):
def __init__(self):
self.message = '请输入正确的数据'
class CircleArea:
def circle(self):
try:
radius = int(input("请输入圆的半径：\n"))
if radius <0:
raise NumericalError()
except NumericalError as e:
print(e.message)
else:
# 计算圆的面积
print(3.14*radius**2)
circle_area = CircleArea()
circle_area.circle()
